import{PARAMS}from'./project.js?v=0.5.0';import{instantiate}from'./wasm.js?v=0.5.0';const index=Object.fromEntries(PARAMS.map(([id],i)=>[id,i]));
export async function renderMix(p,module){const n=p.loopEnd-p.loopStart,mix=[new Float32Array(n),new Float32Array(n)],solo=[1,2,3,4].some(t=>p.params[`solo${t}`]>.5);for(let t=0;t<4;t++){if(p.params[`mute${t+1}`]>.5||solo&&p.params[`solo${t+1}`]<.5)continue;let gain=p.params[`gain${t+1}`],pan=p.params[`pan${t+1}`],gl=gain*(pan>0?1-pan:1),gr=gain*(pan<0?1+pan:1);for(let i=0;i<n;i++){mix[0][i]+=(p.tracks[t][0][i+p.loopStart]||0)*gl;mix[1][i]+=(p.tracks[t][1][i+p.loopStart]||0)*gr;}}const fx=instantiate(module);fx.tape_init_fx(p.rate);for(const [id]of PARAMS)fx.tape_set(index[id],p.params[id]);fx.tape_set(index.monitor,1);if(p.params.fxRoute<.5)fx.tape_set(index.fxType,0);const input=new Float32Array(fx.memory.buffer,fx.tape_input(),256),output=new Float32Array(fx.memory.buffer,fx.tape_output(),256);for(let at=0;at<n;at+=128){const count=Math.min(128,n-at);input.fill(0);for(let i=0;i<count;i++){input[i*2]=mix[0][at+i];input[i*2+1]=mix[1][at+i];}fx.tape_render(count);for(let i=0;i<count;i++){mix[0][at+i]=output[i*2];mix[1][at+i]=output[i*2+1];}if(at%(128*512)===0)await new Promise(r=>setTimeout(r,0));}return mix;}
